content:
:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --badge-bg: #eff6ff;
  --badge-text: #1d4ed8;
  --radius: 8px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  padding: 20px;
}

.app-container {
  max-width: 900px;
  margin: 0 auto;
  background-color: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  overflow: hidden;
}

.header {
  margin-bottom: 20px;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 16px;
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
}

.filter-section {
  margin-bottom: 20px;
  display: flex;
  gap: 12px;
  align-items: center;
}

.search-input {
  width: 100%;
  max-width: 320px;
  padding: 10px 14px;
  font-size: 0.95rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.search-input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.table-container {
  width: 100%;
  overflow-x: auto;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
}

.employee-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.95rem;
  white-space: nowrap;
}

.employee-table th,
.employee-table td {
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-color);
}

.employee-table th {
  background-color: #f1f5f9;
  font-weight: 600;
  color: var(--text-main);
}

.employee-table tbody tr:last-child td {
  border-bottom: none;
}

.employee-table tbody tr:hover {
  background-color: #f8fafc;
}

.th-sortable {
  cursor: pointer;
  user-select: none;
  transition: background-color 0.2s;
}

.th-sortable:hover {
  background-color: #e2e8f0;
}

.badge {
  display: inline-block;
  padding: 4px 8px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--badge-text);
  background-color: var(--badge-bg);
  border-radius: 4px;
}

.no-result {
  text-align: center;
  padding: 32px;
  color: var(--text-muted);
  font-style: italic;
}

@media (max-width: 600px) {
  body {
    padding: 10px;
  }
  .app-container {
    padding: 16px;
  }
  .search-input {
    max-width: 100%;
  }
}

export interface Employee {
  id: number;
  name: string;
  department: string;
  age: number;
}

export type SortField = 'name' | 'department' | 'age';

export type SortOrder = 'asc' | 'desc';

import { useState, useMemo } from 'react';
import './index.css';
import { Employee, SortField, SortOrder } from './types';

const initialEmployees: Employee[] = [
  { id: 1, name: '佐藤 健', department: '開発部', age: 28 },
  { id: 2, name: '鈴木 美咲', department: '人事部', age: 34 },
  { id: 3, name: '高橋 翔', department: '営業部', age: 41 },
  { id: 4, name: '田中 葵', department: '開発部', age: 25 },
  { id: 5, name: '伊藤 蓮', department: 'マーケティング', age: 30 },
  { id: 6, name: '渡辺 さくら', department: '総務部', age: 38 },
  { id: 7, name: '山本 大地', department: '営業部', age: 29 },
  { id: 8, name: '中村 美羽', department: '開発部', age: 32 },
  { id: 9, name: '小林 陽菜', department: '人事部', age: 27 },
  { id: 10, name: '加藤 陸', department: 'マーケティング', age: 45 },
];

export default function App() {
  const [employees] = useState<Employee[]>(initialEmployees);
  const [searchName, setSearchName] = useState<string>('');
  const [sortField, setSortField] = useState<SortField>('name');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('asc');
    }
  };

  const filteredEmployees = useMemo(() => {
    return employees.filter((emp) =>
      emp.name.toLowerCase().includes(searchName.toLowerCase())
    );
  }, [employees, searchName]);

  const sortedEmployees = useMemo(() => {
    return [...filteredEmployees].sort((a, b) => {
      let aVal = a[sortField];
      let bVal = b[sortField];

      if (typeof aVal === 'string' && typeof bVal === 'string') {
        const comparison = aVal.localeCompare(bVal, 'ja');
        return sortOrder === 'asc' ? comparison : -comparison;
      } else {
        if (aVal < bVal) return sortOrder === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortOrder === 'asc' ? 1 : -1;
        return 0;
      }
    });
  }, [filteredEmployees, sortField, sortOrder]);

  const getSortIcon = (field: SortField) => {
    if (sortField !== field) return ' ↕';
    return sortOrder === 'asc' ? ' ▲' : ' ▼';
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">社員一覧</h1>
      </header>

      <div className="filter-section">
        <input
          type="text"
          className="search-input"
          placeholder="名前で絞り込み..."
          value={searchName}
          onChange={(e) => setSearchName(e.target.value)}
        />
      </div>

      <div className="table-container">
        <table className="employee-table">
          <thead>
            <tr>
              <th className="th-sortable" onClick={() => handleSort('name')}>
                名前{getSortIcon('name')}
              </th>
              <th className="th-sortable" onClick={() => handleSort('department')}>
                部署{getSortIcon('department')}
              </th>
              <th className="th-sortable" onClick={() => handleSort('age')}>
                年齢{getSortIcon('age')}
              </th>
            </tr>
          </thead>
          <tbody>
            {sortedEmployees.length > 0 ? (
              sortedEmployees.map((emp) => (
                <tr key={emp.id}>
                  <td>{emp.name}</td>
                  <td>
                    <span className="badge">{emp.department}</span>
                  </td>
                  <td>{emp.age}歳</td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={3} className="no-result">
                  該当する社員が見つかりませんでした。
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
